// Dev-time generator (NOT shipped). Emits code-point range tables.
import { writeFileSync } from 'node:fs';

function ranges(testFn, max) {
  const out = [];
  let start = -1;
  for (let cp = 0; cp <= max; cp++) {
    const ok = testFn(cp);
    if (ok && start < 0) start = cp;
    else if (!ok && start >= 0) { out.push([start, cp - 1]); start = -1; }
  }
  if (start >= 0) out.push([start, max]);
  return out;
}
const isWord = new RegExp('[\\p{L}\\p{N}_]', 'u');
const wordRanges = ranges(cp => isWord.test(String.fromCodePoint(cp)), 0x10FFFF);
const isSpace = new RegExp('[\\s]', 'u');
const spaceRanges = ranges(cp => isSpace.test(String.fromCodePoint(cp)), 0x10FFFF);

// delta-encode: pairs of (gapFromPrevEnd, length)
function encode(rs) {
  let prev = -1; const parts = [];
  for (const [a, b] of rs) { parts.push((a - prev - 1) + ',' + (b - a)); prev = b; }
  return parts.join(' ');
}
let src = `// AUTO-GENERATED code point tables. Delta-encoded "gap,len" pairs.
// wordRanges approximates Python's regex \\\\w ([\\\\p{L}\\\\p{N}_]).
// spaceRanges approximates Python's regex \\\\s.
