  '${encode(wordRanges)}';
export const SPACE_RANGES_ENCODED =
  '${encode(spaceRanges)}';
`;
writeFileSync('/tmp/dev/unicodeTables.mjs', src);
console.log('word ranges:', wordRanges.length, 'space ranges:', spaceRanges.length, 'bytes:', src.length);
console.log('space:', JSON.stringify(spaceRanges));
