// Character level helpers.
//
// Everything in this port is written as an explicit scanner over code points so
// that the behaviour of the original Python implementation (which is specified
// in terms of Python's own character classes) can be mirrored exactly.

import { WORD_RANGES_ENCODED, SPACE_RANGES } from './unicodeTables.mjs';

function decodeRanges(encoded) {
  const ranges = [];
  let prev = -1;
  for (const pair of encoded.split(' ')) {
    const comma = pair.indexOf(',');
    const gap = Number(pair.slice(0, comma));
    const len = Number(pair.slice(comma + 1));
    const start = prev + 1 + gap;
    prev = start + len;
    ranges.push(start, prev);
  }
  return ranges;
}

const WORD_RANGES = decodeRanges(WORD_RANGES_ENCODED);

function inFlatRanges(ranges, cp) {
  let lo = 0;
  let hi = ranges.length / 2 - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (cp < ranges[mid * 2]) hi = mid - 1;
    else if (cp > ranges[mid * 2 + 1]) lo = mid + 1;
    else return true;
  }
  return false;
}

/** True for the code points Python's `re` module treats as `\w`. */
export function isWordCodePoint(cp) {
  if (cp === undefined) return false;
  if (cp < 128) {
    return (
      (cp >= 48 && cp <= 57) ||
      (cp >= 65 && cp <= 90) ||
      (cp >= 97 && cp <= 122) ||
      cp === 95
    );
  }
  return inFlatRanges(WORD_RANGES, cp);
}

/** True for the code points Python's `re` module treats as `\s`. */
export function isSpaceCodePoint(cp) {
  if (cp === undefined) return false;
  for (const [lo, hi] of SPACE_RANGES) {
    if (cp >= lo && cp <= hi) return true;
    if (cp < lo) return false;
  }
  return false;
}

export function isSpaceChar(ch) {
  return ch !== undefined && ch !== '' && isSpaceCodePoint(ch.charCodeAt(0));
}

export function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

export function isAsciiLetter(ch) {
  return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');
}

export function isHexDigit(ch) {
  return isDigit(ch) || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
}

export function isAlnumAscii(ch) {
  return isDigit(ch) || isAsciiLetter(ch);
}

/**
 * The code point ending at `index` (exclusive), honouring surrogate pairs, so
 * that lookbehind assertions see whole characters the way Python does.
 */
export function codePointBefore(text, index) {
  if (index <= 0) return undefined;
  const code = text.charCodeAt(index - 1);
  if (code >= 0xdc00 && code <= 0xdfff && index >= 2) {
    const high = text.charCodeAt(index - 2);
    if (high >= 0xd800 && high <= 0xdbff) {
      return (high - 0xd800) * 0x400 + (code - 0xdc00) + 0x10000;
    }
  }
  return code;
}

/** Length in UTF-16 units of the single character starting at `index`. */
export function charLengthAt(text, index) {
  const code = text.charCodeAt(index);
  if (code >= 0xd800 && code <= 0xdbff && index + 1 < text.length) {
    const low = text.charCodeAt(index + 1);
    if (low >= 0xdc00 && low <= 0xdfff) return 2;
  }
  return 1;
}

/** `text[index]` is a `\w` character. */
export function isWordAt(text, index) {
  if (index < 0 || index >= text.length) return false;
  return isWordCodePoint(text.codePointAt(index));
}

/** The character preceding `index` is a `\w` character. */
export function isWordBefore(text, index) {
  return isWordCodePoint(codePointBefore(text, index));
}

