// String helpers mirroring the Python string methods used by the original
// implementation. Python's `strip()` family removes *any* whitespace, which is
// not the same set JavaScript's `trim()` uses, so they are reimplemented here.

import { isSpaceChar } from './chars.mjs';

export function lstrip(text, chars) {
  let i = 0;
  while (i < text.length) {
    const ch = text[i];
    if (chars === undefined ? isSpaceChar(ch) : chars.indexOf(ch) !== -1) i += 1;
    else break;
  }
  return text.slice(i);
}

export function rstrip(text, chars) {
  let i = text.length;
  while (i > 0) {
    const ch = text[i - 1];
    if (chars === undefined ? isSpaceChar(ch) : chars.indexOf(ch) !== -1) i -= 1;
    else break;
  }
  return text.slice(0, i);
}

export function strip(text, chars) {
  return lstrip(rstrip(text, chars), chars);
}

/** Python's truthiness test for `text.strip()`. */
export function hasContent(text) {
  if (text === undefined || text === null) return false;
  const str = String(text);
  for (let i = 0; i < str.length; i += 1) {
    if (!isSpaceChar(str[i])) return true;
  }
  return false;
}

export function splitLines(text) {
  return String(text).split('\n');
}

/** Python's `str.expandtabs(tabsize)`. */
export function expandTabs(text, tabSize) {
  let out = '';
  let column = 0;
  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];
    if (ch === '\t') {
      const width = tabSize - (column % tabSize);
      out += ' '.repeat(width);
      column += width;
    } else {
      out += ch;
      if (ch === '\n' || ch === '\r') column = 0;
      else column += 1;
    }
  }
  return out;
}

export function replaceAll(text, search, replacement) {
  return String(text).split(search).join(replacement);
}

export function startsWithAt(text, needle, index) {
  return text.startsWith(needle, index);
}

/** Count of `needle` occurrences inside `text[start:end]`. */
export function countBetween(text, needle, start, end) {
  let count = 0;
  let i = start;
  for (;;) {
    const found = text.indexOf(needle, i);
    if (found === -1 || found >= end) break;
    count += 1;
    i = found + needle.length;
  }
  return count;
}

