// A minimal stand-in for Python's `xml.etree.ElementTree` covering only the
// features the Markdown pipeline relies on: ordered children, `text`/`tail`
// strings and insertion-ordered attributes.

/**
 * Marker type for text which must not be processed by the inline patterns.
 * Extending `String` keeps it usable everywhere a plain string is expected,
 * exactly like Python's `AtomicString`.
 */
export class AtomicString extends String {}

export function atomic(value) {
  return new AtomicString(value === undefined || value === null ? '' : value);
}

export function isAtomic(value) {
  return value instanceof AtomicString;
}

export function isStringLike(value) {
  return typeof value === 'string' || value instanceof String;
}

export class Element {
  constructor(tag) {
    this.tag = tag;
    this.attrib = new Map();
    this.text = null;
    this.tail = null;
    this.children = [];
  }

  get length() {
    return this.children.length;
  }

  append(child) {
    this.children.push(child);
  }

  insert(index, child) {
    this.children.splice(index, 0, child);
  }

  remove(child) {
    const index = this.children.indexOf(child);
    if (index !== -1) this.children.splice(index, 1);
  }

  indexOf(child) {
    return this.children.indexOf(child);
  }

  get(name) {
    return this.attrib.has(name) ? this.attrib.get(name) : null;
  }

  set(name, value) {
    this.attrib.set(name, value);
  }

  items() {
    return [...this.attrib.entries()];
  }

  /** Last child, or `null` when there are none. */
  get lastChild() {
    return this.children.length ? this.children[this.children.length - 1] : null;
  }

  /** Depth first iteration over this element and all of its descendants. */
  * iter(tag) {
    if (tag === undefined || tag === this.tag) yield this;
    for (const child of this.children) yield* child.iter(tag);
  }
}

export function subElement(parent, tag) {
  const element = new Element(tag);
  parent.append(element);
  return element;
}

