// HTML serialisation of an element tree.
//
// The escaping rules are the ones used by Markdown itself rather than the ones
// from the standard library: an ampersand is only escaped when it does not
// already introduce a character reference, which is what allows pre-escaped
// code spans to survive serialisation untouched.

import { HTML_EMPTY } from '../util/constants.mjs';
import { isDigit, isHexDigit, isAsciiLetter, isAlnumAscii } from '../util/chars.mjs';

/** True when a character reference starts at `index` (which holds the `&`). */
function isCharacterReference(text, index) {
  let i = index + 1;
  if (i >= text.length) return false;
  if (text[i] === '#') {
    i += 1;
    if (text[i] === 'x' || text[i] === 'X') {
      i += 1;
      const start = i;
      while (i < text.length && isHexDigit(text[i])) i += 1;
      if (i === start) return false;
    } else {
      const start = i;
      while (i < text.length && isDigit(text[i])) i += 1;
      if (i === start) return false;
    }
  } else if (isAsciiLetter(text[i])) {
    i += 1;
    while (i < text.length && isAlnumAscii(text[i])) i += 1;
  } else {
    return false;
  }
  return text[i] === ';';
}

function escapeAmpersands(text) {
  if (text.indexOf('&') === -1) return text;
  let out = '';
  for (let i = 0; i < text.length; i += 1) {
    if (text[i] === '&' && !isCharacterReference(text, i)) out += '&amp;';
    else out += text[i];
  }
  return out;
}

function escapeCdata(text) {
  let out = escapeAmpersands(String(text));
  if (out.indexOf('<') !== -1) out = out.split('<').join('&lt;');
  if (out.indexOf('>') !== -1) out = out.split('>').join('&gt;');
  return out;
}

function escapeAttrib(text) {
  let out = escapeCdata(text);
  if (out.indexOf('"') !== -1) out = out.split('"').join('&quot;');
  return out;
}

function serializeElement(parts, element) {
  const tag = element.tag;
  parts.push('<' + tag);
  const items = element.items();
  items.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
  for (const [name, value] of items) {
    parts.push(' ' + name + '="' + escapeAttrib(value) + '"');
  }
  const empty = HTML_EMPTY.has(tag.toLowerCase());
  parts.push(empty ? ' />' : '>');
  if (element.text) {
    if (tag.toLowerCase() === 'script' || tag.toLowerCase() === 'style') {
      parts.push(String(element.text));
    } else {
      parts.push(escapeCdata(element.text));
    }
  }
  for (const child of element.children) serializeElement(parts, child);
  if (!empty) parts.push('</' + tag + '>');
  if (element.tail) parts.push(escapeCdata(element.tail));
}

export function toHtmlString(element) {
  const parts = [];
  serializeElement(parts, element);
  return parts.join('');
}

