// Hand written scanners for the token shapes Python's `html.parser` recognises,
// including the two tweaks Markdown applies to it: processing instructions must
// end with `?>` and entity references must be closed by a semicolon.

import { isSpaceChar, isAsciiLetter, isDigit, isHexDigit, isAlnumAscii } from '../util/chars.mjs';

const NAME_STOP = '\t\n\r\f />�`';
const ATTR_NAME_STOP = '\t\n\r\f /=>';

