  let i = index;
  while (i < text.length && isSpaceChar(text[i])) i += 1;
  return i;
}

/** `<[a-zA-Z]` */
export function isStartTagOpen(text, index) {
  return text[index] === '<' && isAsciiLetter(text[index + 1] || '');
