  while (i < text.length && '\t\n\r\f />�'.indexOf(text[i]) === -1) i += 1;
  const name = text.slice(index, i);
  for (;;) {
    if (i < text.length && isSpaceChar(text[i])) i += 1;
    else if (text[i] === '/' && text[i + 1] !== '>') i += 1;
    else break;
  }
  return { name, end: i };
