// A port of the subset of CPython's `html.parser.HTMLParser` that Markdown
// depends on. Subclasses receive the same callbacks as the Python original;
// positions are tracked as absolute offsets into the fed document, which is
// equivalent to the line/offset pair the Python class maintains.

import { isSpaceChar, isAsciiLetter } from '../util/chars.mjs';
import { strip } from '../util/strings.mjs';
import {
  isStartTagOpen, matchTagName, matchAttribute, locateStartTagEnd, matchEndTag,
  searchCommentClose, searchMarkedSectionClose, searchMsMarkedSectionClose,
  scanName, matchEntityRef, matchCharRef, skipSpaces
} from './scanners.mjs';

const CDATA_CONTENT_ELEMENTS = ['script', 'style'];
const INCOMPLETE_TAG_TAIL = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ=/';
const MARKED_SECTIONS = ['temp', 'cdata', 'ignore', 'include', 'rcdata'];
const MS_SECTIONS = ['if', 'else', 'endif'];

export class HTMLParser {
  constructor() {
    this.rawdata = '';
    this.cdataElem = null;
    this.tokenStart = 0;
  }

  feed(data) {
    this.rawdata += data;
    this.goahead(false);
  }

  close() {
    this.goahead(true);
  }

  setCdataMode(elem) {
    this.cdataElem = elem.toLowerCase();
  }

  clearCdataMode() {
    this.cdataElem = null;
  }

  /** Index of the next `<` or `&`, or of the closing tag while in CDATA mode. */
  findInteresting(text, from) {
    if (this.cdataElem) {
      const needle = '</';
      let i = from;
      for (;;) {
        const found = text.indexOf(needle, i);
        if (found === -1) return -1;
        const after = skipSpaces(text, found + 2);
        if (text.slice(after, after + this.cdataElem.length).toLowerCase() === this.cdataElem) {
          return found;
        }
        i = found + 1;
      }
    }
    for (let i = from; i < text.length; i += 1) {
      if (text[i] === '<' || text[i] === '&') return i;
    }
    return -1;
  }

  goahead(end) {
    const rawdata = this.rawdata;
    const n = rawdata.length;
    let i = 0;
    while (i < n) {
      const found = this.findInteresting(rawdata, i);
      let j = found;
      if (found === -1) {
        if (this.cdataElem) break;
        j = n;
      }
      if (i < j) {
        this.tokenStart = i;
        this.handleData(rawdata.slice(i, j));
      }
      i = j;
      if (i === n) break;
      this.tokenStart = i;
      let k;
      if (rawdata[i] === '<') {
        if (isStartTagOpen(rawdata, i)) k = this.parseStartTag(i);
        else if (rawdata.startsWith('</', i)) k = this.parseEndTag(i);
        else if (rawdata.startsWith('<!--', i)) k = this.parseComment(i);
        else if (rawdata.startsWith('<?', i)) k = this.parsePi(i);
        else if (rawdata.startsWith('<!', i)) k = this.parseHtmlDeclaration(i);
        else if (i + 1 < n) { this.handleData('<'); k = i + 1; }
        else if (end) { this.handleData('<'); k = i + 1; }
        else break;
        if (k < 0) {
          if (!end) break;
          k = rawdata.indexOf('>', i + 1);
          if (k === -1) {
            k = rawdata.indexOf('<', i + 1);
            if (k === -1) k = i + 1;
          } else {
            k += 1;
          }
          this.tokenStart = i;
          this.handleData(rawdata.slice(i, k));
        }
        i = k;
      } else if (rawdata.startsWith('&#', i)) {
        const match = matchCharRef(rawdata, i);
        if (match) {
          this.tokenStart = i;
          this.handleCharRef(match.name);
          i = rawdata[match.end - 1] === ';' ? match.end : match.end - 1;
          continue;
        }
        if (rawdata.indexOf(';', i) !== -1) {
          this.tokenStart = i;
          this.handleData(rawdata.slice(i, i + 2));
          i += 2;
        }
        break;
      } else {
        const match = matchEntityRef(rawdata, i);
        if (match) {
          this.tokenStart = i;
          this.handleEntityRef(match.name);
          i = rawdata[match.end - 1] === ';' ? match.end : match.end - 1;
          continue;
        }
        // Markdown narrows the "incomplete entity" pattern to the one above, so
        // an unmatched `&` is always literal text.
        if (i + 1 < n) {
          this.tokenStart = i;
          this.handleData('&');
          i += 1;
        } else {
          break;
        }
      }
    }
    if (end && i < n) {
      this.tokenStart = i;
      this.handleData(rawdata.slice(i, n));
      i = n;
    }
    this.rawdata = rawdata.slice(i);
  }

  getStartTagText() {
    return this.starttagText;
  }

  parseStartTag(i) {
    this.starttagText = null;
    const endpos = this.checkForWholeStartTag(i);
    if (endpos < 0) return endpos;
    const rawdata = this.rawdata;
    this.starttagText = rawdata.slice(i, endpos);

    const attrs = [];
    const nameMatch = matchTagName(rawdata, i + 1);
    let k = nameMatch.end;
    const tag = nameMatch.name.toLowerCase();
    while (k < endpos) {
      const attr = matchAttribute(rawdata, k);
      if (!attr) break;
      let value = attr.value;
      if (value !== null) {
        const first = value.slice(0, 1);
        const last = value.slice(-1);
        if ((first === "'" && last === "'") || (first === '"' && last === '"')) {
          value = value.slice(1, -1);
        }
      }
      attrs.push([attr.name.toLowerCase(), value]);
      k = attr.end;
    }
    const tail = strip(rawdata.slice(k, endpos));
    if (tail !== '>' && tail !== '/>') {
      this.tokenStart = i;
      this.handleData(rawdata.slice(i, endpos));
      return endpos;
    }
    this.tokenStart = i;
    if (tail.endsWith('/>')) {
      this.handleStartEndTag(tag, attrs);
    } else {
      this.handleStartTag(tag, attrs);
      if (CDATA_CONTENT_ELEMENTS.indexOf(tag) !== -1) this.setCdataMode(tag);
    }
    return endpos;
  }

  checkForWholeStartTag(i) {
    const rawdata = this.rawdata;
    const j = locateStartTagEnd(rawdata, i);
    const next = rawdata.slice(j, j + 1);
    if (next === '>') return j + 1;
    if (next === '/') {
      if (rawdata.startsWith('/>', j)) return j + 2;
      return -1;
    }
    if (next === '') return -1;
    if (INCOMPLETE_TAG_TAIL.indexOf(next) !== -1) return -1;
    if (j > i) return j;
    return i + 1;
  }

  parseEndTag(i) {
    const rawdata = this.rawdata;
    const gt = rawdata.indexOf('>', i + 1);
    if (gt === -1) return -1;
    let gtpos = gt + 1;
    const match = matchEndTag(rawdata, i);
    if (!match) {
      if (this.cdataElem !== null) {
        this.tokenStart = i;
        this.handleData(rawdata.slice(i, gtpos));
        return gtpos;
      }
      const nameMatch = matchTagName(rawdata, i + 2);
      if (!nameMatch) {
        if (rawdata.slice(i, i + 3) === '</>') return i + 3;
        return this.parseBogusComment(i);
      }
      const tagname = nameMatch.name.toLowerCase();
      gtpos = rawdata.indexOf('>', nameMatch.end);
      this.tokenStart = i;
      this.handleEndTag(tagname);
      return gtpos + 1;
    }
    const elem = match.name.toLowerCase();
    if (this.cdataElem !== null && elem !== this.cdataElem) {
      this.tokenStart = i;
      this.handleData(rawdata.slice(i, gtpos));
      return gtpos;
    }
    this.tokenStart = i;
    this.handleEndTag(elem);
    this.clearCdataMode();
    return match.end;
  }

  parseComment(i) {
    const match = searchCommentClose(this.rawdata, i + 4);
    if (!match) return -1;
    this.tokenStart = i;
    this.handleComment(this.rawdata.slice(i + 4, match.start));
    return match.end;
  }

  parsePi(i) {
    const rawdata = this.rawdata;
    // Markdown restricts the closing sequence of a processing instruction.
    const close = rawdata.indexOf('?>', i + 2);
    if (close === -1) return -1;
    this.tokenStart = i;
    this.handlePi(rawdata.slice(i + 2, close));
    return close + 2;
  }

  parseHtmlDeclaration(i) {
    const rawdata = this.rawdata;
    if (rawdata.startsWith('<!--', i)) return this.parseComment(i);
    if (rawdata.startsWith('<![', i)) return this.parseMarkedSection(i);
    if (rawdata.slice(i, i + 9).toLowerCase() === '<!doctype') {
      const gtpos = rawdata.indexOf('>', i + 9);
      if (gtpos === -1) return -1;
      this.tokenStart = i;
      this.handleDecl(rawdata.slice(i + 2, gtpos));
      return gtpos + 1;
    }
    return this.parseBogusComment(i);
  }

  parseMarkedSection(i) {
    const rawdata = this.rawdata;
    const section = scanName(rawdata, i + 3);
    if (!section) return -1;
    let match = null;
    if (MARKED_SECTIONS.indexOf(section.name) !== -1) {
      match = searchMarkedSectionClose(rawdata, i + 3);
    } else if (MS_SECTIONS.indexOf(section.name) !== -1) {
      match = searchMsMarkedSectionClose(rawdata, i + 3);
    } else {
      return -1;
    }
    if (!match) return -1;
    this.tokenStart = i;
    this.unknownDecl(rawdata.slice(i + 3, match.start));
    return match.end;
  }

  parseBogusComment(i) {
    const pos = this.rawdata.indexOf('>', i + 2);
    if (pos === -1) return -1;
    this.tokenStart = i;
    this.handleComment(this.rawdata.slice(i + 2, pos));
    return pos + 1;
  }

  /* Callbacks -- overridden by subclasses. */
  handleData() {}
  handleStartTag() {}
  handleEndTag() {}
  handleStartEndTag(tag, attrs) {
    this.handleStartTag(tag, attrs);
    this.handleEndTag(tag);
  }
  handleComment() {}
  handleDecl() {}
  handlePi() {}
  unknownDecl() {}
  handleCharRef() {}
  handleEntityRef() {}
}

export { isSpaceChar, isAsciiLetter };

