// Extracts block level raw HTML from the document, replacing each block with a
// stash placeholder so the Markdown parsers never look inside it.

import { HTMLParser } from '../html/htmlParser.mjs';
import { isBlockLevel } from '../util/constants.mjs';
import { hasContent } from '../util/strings.mjs';

const EMPTY_TAGS = new Set(['hr']);

/** `^[ ]{0,3}\n` */
function startsWithBlankLine(text) {
  let i = 0;
  while (i < 4 && text[i] === ' ') i += 1;
  return text[i] === '\n';
}

export class HTMLExtractor extends HTMLParser {
  constructor(stash) {
    super();
    this.stash = stash;
    this.inraw = false;
    this.intail = false;
    this.stack = [];
    this.cache = [];
    this.cleandoc = [];
  }

  close() {
    super.close();
    // Anything still buffered belongs to an unclosed raw block.
    if (this.cache.length) {
      this.cleandoc.push(this.stash.store(this.cache.join('')));
      this.cache = [];
    }
  }

  /** True when the current token starts a line (up to three spaces of indent). */
  atLineStart() {
    const pos = this.tokenStart;
    if (pos === 0) return true;
    const lineStart = this.rawdata.lastIndexOf('\n', pos - 1) + 1;
    const column = pos - lineStart;
    if (column === 0) return true;
    if (column > 3) return false;
    return !hasContent(this.rawdata.slice(lineStart, pos));
  }

  /** Original source text of the end tag which starts at the current token. */
  getEndTagText(tag) {
    const start = this.tokenStart;
    const gt = this.rawdata.indexOf('>', start);
    if (gt !== -1) return this.rawdata.slice(start, gt + 1);
    return '</' + tag + '>';
  }

  handleStartTag(tag, attrs) {
    if (EMPTY_TAGS.has(tag)) {
      this.handleStartEndTag(tag, attrs);
      return;
    }
    if (isBlockLevel(tag) && (this.intail || (this.atLineStart() && !this.inraw))) {
      // A new raw block starts here.
      this.inraw = true;
      this.cleandoc.push('\n');
    }
    const text = this.getStartTagText();
    if (this.inraw) {
      this.stack.push(tag);
      this.cache.push(text);
    } else {
      this.cleandoc.push(text);
      if (tag === 'script' || tag === 'style') {
        // Presumably a standalone tag inside a code span.
        this.clearCdataMode();
      }
    }
  }

  handleEndTag(tag) {
    const text = this.getEndTagText(tag);
    if (this.inraw) {
      this.cache.push(text);
      if (this.stack.indexOf(tag) !== -1) {
        while (this.stack.length) {
          if (this.stack.pop() === tag) break;
        }
      }
      if (this.stack.length === 0) {
        if (startsWithBlankLine(this.rawdata.slice(this.tokenStart + text.length))) {
          // Preserve the blank line which ends the raw block.
          this.cache.push('\n');
        } else {
          // More content follows on the same line.
          this.intail = true;
        }
        this.inraw = false;
        this.cleandoc.push(this.stash.store(this.cache.join('')));
        this.cleandoc.push('\n\n');
        this.cache = [];
      }
    } else {
      this.cleandoc.push(text);
    }
  }

  handleData(data) {
    if (this.intail && data.indexOf('\n') !== -1) this.intail = false;
    if (this.inraw) this.cache.push(data);
    else this.cleandoc.push(data);
  }

  handleEmptyTag(data, isBlock) {
    if (this.inraw || this.intail) {
      this.cache.push(data);
    } else if (this.atLineStart() && isBlock) {
      let text = data;
      if (startsWithBlankLine(this.rawdata.slice(this.tokenStart + data.length))) {
        text += '\n';
      } else {
        this.intail = true;
      }
      const item = this.cleandoc.length ? String(this.cleandoc[this.cleandoc.length - 1]) : '';
      if (!item.endsWith('\n\n') && item.endsWith('\n')) this.cleandoc.push('\n');
      this.cleandoc.push(this.stash.store(text));
      this.cleandoc.push('\n\n');
    } else {
      this.cleandoc.push(data);
    }
  }

  handleStartEndTag(tag) {
    this.handleEmptyTag(this.getStartTagText(), isBlockLevel(tag));
  }

  handleCharRef(name) {
    this.handleEmptyTag('&#' + name + ';', false);
  }

  handleEntityRef(name) {
    this.handleEmptyTag('&' + name + ';', false);
  }

  handleComment(data) {
    this.handleEmptyTag('<!--' + data + '-->', true);
  }

  handleDecl(data) {
    this.handleEmptyTag('<!' + data + '>', true);
  }

  handlePi(data) {
    this.handleEmptyTag('<?' + data + '>', true);
  }

  unknownDecl(data) {
    const end = data.startsWith('CDATA[') ? ']]>' : ']>';
    this.handleEmptyTag('<![' + data + end, true);
  }

  parseBogusComment(i) {
    // Bogus comments are preserved verbatim rather than turned into comments.
    const pos = this.rawdata.indexOf('>', i + 2);
    if (pos === -1) return -1;
    this.tokenStart = i;
    this.handleEmptyTag(this.rawdata.slice(i, pos + 1), false);
    return pos + 1;
  }
}

/** Preprocessor: replace raw HTML blocks with stash placeholders. */
export function htmlBlockPreprocessor(lines, stash) {
  const parser = new HTMLExtractor(stash);
  parser.feed(lines.join('\n'));
  parser.close();
  return parser.cleandoc.join('').split('\n');
}

