// First preprocessor: normalise line endings, tabs and whitespace-only lines.

import { TAB_LENGTH, STX, ETX } from '../util/constants.mjs';
import { expandTabs, replaceAll } from '../util/strings.mjs';

/** Replace every run of spaces that makes up a whole line with nothing. */
function blankOutSpaceOnlyLines(source) {
  let out = '';
  let i = 0;
  while (i < source.length) {
    const ch = source[i];
    out += ch;
    i += 1;
    if (ch !== '\n') continue;
    let j = i;
    while (j < source.length && source[j] === ' ') j += 1;
    if (j > i && source[j] === '\n') {
      out += '\n';
      i = j + 1;
    }
  }
  return out;
}

export function normalizeWhitespace(lines) {
  let source = lines.join('\n');
  source = replaceAll(source, STX, '');
  source = replaceAll(source, ETX, '');
  source = replaceAll(source, '\r\n', '\n');
  source = replaceAll(source, '\r', '\n');
  source += '\n\n';
  source = expandTabs(source, TAB_LENGTH);
  source = blankOutSpaceOnlyLines(source);
  return source.split('\n');
}

