export function matchSetextHeader(block) {
  const newline = block.indexOf('\n');
  if (newline === -1) return null;
  let i = newline + 1;
  if (block[i] !== '=' && block[i] !== '-') return null;
  while (block[i] === '=' || block[i] === '-') i += 1;
  while (block[i] === ' ') i += 1;
  if (i >= block.length || block[i] === '\n') return { end: i };
