/** `^.*?\n[=-]+[ ]*(\n|$)` anchored at the start of `block`. */
export function matchSetextHeader(block) {
  const newline = block.indexOf('\n');
  if (newline === -1) return null;
  let i = newline + 1;
  if (block[i] !== '=' && block[i] !== '-') return null;
  while (block[i] === '=' || block[i] === '-') i += 1;
  while (block[i] === ' ') i += 1;
  if (i >= block.length || block[i] === '\n') return { end: i };
  return null;
}

/**
 * `^[ ]{0,3}((-+[ ]{0,2}){3,}|(_+[ ]{0,2}){3,}|(\*+[ ]{0,2}){3,})[ ]*$` with
 * the multiline flag. Returns `{ start, end }` for the first matching line.
 */
export function searchHorizontalRule(block) {
  let lineStart = 0;
  for (;;) {
    let lineEnd = block.indexOf('\n', lineStart);
    if (lineEnd === -1) lineEnd = block.length;
    const line = block.slice(lineStart, lineEnd);
    for (const marker of ['-', '_', '*']) {
      if (matchesRuleLine(line, marker)) return { start: lineStart, end: lineEnd };
    }
    if (lineEnd === block.length) return null;
    lineStart = lineEnd + 1;
  }
}

/**
 * A rule line is a run of marker characters, optionally broken up by groups of
 * one or two spaces, with at least three markers in total.
 */
function matchesRuleLine(line, marker) {
  let i = leadingSpaces(line, 0, 3);
  if (line[i] !== marker) return false;
  let markers = 0;
  while (i < line.length) {
    if (line[i] === marker) {
      markers += 1;
      i += 1;
    } else if (line[i] === ' ') {
      let spaces = 0;
      while (line[i + spaces] === ' ') spaces += 1;
      if (i + spaces >= line.length) {
        i = line.length;
      } else if (line[i + spaces] === marker && spaces <= 2) {
        i += spaces;
      } else {
        return false;
      }
    } else {
      return false;
    }
  }
  return markers >= 3;
}

/** `(^|\n)[ ]{0,3}>[ ]?(.*)` anchored at `index`. */
function matchBlockQuoteAt(block, index) {
  const indent = leadingSpaces(block, index, 3);
  let i = index + indent;
  if (block[i] !== '>') return null;
  i += 1;
  if (block[i] === ' ') i += 1;
  let end = block.indexOf('\n', i);
  if (end === -1) end = block.length;
  return { content: block.slice(i, end), end };
}

/** `(^|\n)[ ]{0,3}>[ ]?(.*)` searched from the start of `block`. */
export function searchBlockQuote(block) {
  for (let pos = 0; pos <= block.length; pos += 1) {
    if (pos > 0 && block[pos - 1] !== '\n') continue;
    const found = matchBlockQuoteAt(block, pos);
    if (found) return { start: pos > 0 ? pos - 1 : 0, ...found };
  }
  return null;
}

/** The same pattern anchored at the start of a single line. */
export function matchBlockQuoteLine(line) {
  return matchBlockQuoteAt(line, 0);
}

/** `^[ ]{0,3}\d+\.[ ]+(.*)` anchored at the start of `line`. */
export function matchOrderedItem(line) {
  const item = matchAnyItem(line);
  if (!item || item.marker.length < 2) return null;
  return item;
}

/** `^[ ]{0,3}[*+-][ ]+(.*)` anchored at the start of `line`. */
export function matchUnorderedItem(line) {
  const item = matchAnyItem(line);
  if (!item || item.marker.length !== 1) return null;
  return item;
}

/**
 * `^[ ]{0,3}((\d+\.)|[*+-])[ ]+(.*)` anchored at the start of `line`: a list
 * item of either kind. The marker is `"*"`, `"+"`, `"-"` or e.g. `"12."`.
 */
export function matchAnyItem(line) {
  let i = leadingSpaces(line, 0, TAB_LENGTH - 1);
  const markerStart = i;
  while (isDigit(line[i])) i += 1;
  if (i > markerStart) {
    if (line[i] !== '.') return null;
    i += 1;
  } else if (line[i] === '*' || line[i] === '+' || line[i] === '-') {
    i += 1;
  } else {
    return null;
  }
  const marker = line.slice(markerStart, i);
  const spacesStart = i;
  while (line[i] === ' ') i += 1;
  if (i === spacesStart) return null;
  return { marker, content: line.slice(i) };
}

/** `^[ ]{4,7}((\d+\.)|[*+-])[ ]+.*` anchored at the start of `line`. */
export function isIndentedItem(line) {
  let indent = 0;
  while (line[indent] === ' ') indent += 1;
  if (indent < TAB_LENGTH || indent > TAB_LENGTH * 2 - 1) return false;
  return matchAnyItem(line.slice(indent)) !== null;
}

/** Number of whole indents at the start of `block`, i.e. `^(([ ]{4})+)`. */
export function matchIndentLevel(block) {
  let count = 0;
  while (block.startsWith(' '.repeat(TAB_LENGTH), count * TAB_LENGTH)) count += 1;
  return count;
}

/** True when a multiline `$` can match at `index`. */
function atLineEnd(block, index) {
  return index >= block.length || block[index] === '\n';
}

/**
 * `^[ ]{0,3}\[([^\[\]]*)\]:[ ]*\n?[ ]*([^\s]+)[ ]*(?:\n?[ ]*((["'])(.*)\4|\((.*)\))[ ]*)?$`
 * with the multiline flag, searched from the start of `block`.
 */
export function searchReference(block) {
  let lineStart = 0;
  for (;;) {
    const found = matchReferenceAt(block, lineStart);
    if (found) return found;
    const nl = block.indexOf('\n', lineStart);
    if (nl === -1) return null;
    lineStart = nl + 1;
  }
}

function matchReferenceAt(block, start) {
  let i = start + leadingSpaces(block, start, 3);
  if (block[i] !== '[') return null;
  i += 1;
  const idStart = i;
  while (i < block.length && block[i] !== '[' && block[i] !== ']') i += 1;
  if (block[i] !== ']') return null;
  const id = block.slice(idStart, i);
  i += 1;
  if (block[i] !== ':') return null;
  i += 1;
  while (block[i] === ' ') i += 1;
  if (block[i] === '\n') {
    i += 1;
    while (block[i] === ' ') i += 1;
  }
  const linkStart = i;
  while (i < block.length && !isSpaceChar(block[i])) i += 1;
  if (i === linkStart) return null;
  const link = block.slice(linkStart, i);
  const afterLink = i;
  while (block[i] === ' ') i += 1;
  const withoutTitle = i;

  let titleStart = afterLink;
  while (block[titleStart] === ' ') titleStart += 1;
  if (block[titleStart] === '\n') {
    titleStart += 1;
    while (block[titleStart] === ' ') titleStart += 1;
  }
  const quote = block[titleStart];
  if (quote === '"' || quote === "'" || quote === '(') {
    const closer = quote === '(' ? ')' : quote;
    let lineEnd = block.indexOf('\n', titleStart);
    if (lineEnd === -1) lineEnd = block.length;
    // The title body is greedy, so prefer the right-most possible closer.
    for (let close = lineEnd - 1; close > titleStart; close -= 1) {
      if (block[close] !== closer) continue;
      let after = close + 1;
      while (block[after] === ' ') after += 1;
      if (atLineEnd(block, after)) {
        return { start, end: after, id, link, title: block.slice(titleStart + 1, close) };
      }
    }
  }
  if (atLineEnd(block, withoutTitle)) {
    return { start, end: withoutTitle, id, link, title: null };
  }
  return null;
}

