// Line oriented scanners used by the block level processors. Each function
// mirrors one regular expression from the original implementation.

import { isDigit, isSpaceChar } from '../util/chars.mjs';
import { TAB_LENGTH } from '../util/constants.mjs';

/** Count the leading spaces of `text` starting at `index`, capped at `max`. */
function leadingSpaces(text, index, max) {
  let count = 0;
  while (count < max && text[index + count] === ' ') count += 1;
  return count;
}

/**
 * `(?:^|\n)(#{1,6})((?:\\.|[^\\])*?)#*(?:\n|$)` searched from the start.
 * Returns `{ start, end, level, header }`.
 */
export function searchHashHeader(block) {
  for (let pos = 0; pos <= block.length; pos += 1) {
    // The match must start at the beginning of the block or after a newline.
    let cursor = pos;
    if (pos > 0) {
      if (block[pos - 1] !== '\n') continue;
    }
    let hashes = 0;
    while (hashes < 6 && block[cursor + hashes] === '#') hashes += 1;
    if (hashes === 0) continue;
    cursor += hashes;
    // `((?:\\.|[^\\])*?)#*(?:\n|$)` is lazy, so grow the header one unit at a
    // time and take the first position where the rest of the pattern matches.
    let scan = cursor;
    for (;;) {
      let after = scan;
      while (block[after] === '#') after += 1;
      if (after >= block.length || block[after] === '\n') {
        return {
          start: pos > 0 ? pos - 1 : 0,
          end: after >= block.length ? after : after + 1,
          level: hashes,
          header: block.slice(cursor, scan)
        };
      }
      if (scan >= block.length) break;
      // Advance over one `\\.` or one non-backslash character.
      if (block[scan] === '\\') {
        if (scan + 1 >= block.length) break;
        scan += 2;
      } else {
        scan += 1;
      }
    }
  }
  return null;
}

/** `^.*?\n[=-]+[ ]*(\n|$)` anchored at the start of `block`. */
export function matchSetextHeader(block) {
  let newline = -1;
  for (;;) {
    newline = block.indexOf('\n', newline + 1);
    if (newline === -1) return null;
    let i = newline + 1;
    const marker = block[i];
    if (marker !== '=' && marker !== '-') continue;
    while (block[i] === marker || block[i] === '=' || block[i] === '-') i += 1;
    while (block[i] === ' ') i += 1;
    if (i >= block.length || block[i] === '\n') return { end: i };
  }
}

/**
 * `^[ ]{0,3}((-+[ ]{0,2}){3,}|(_+[ ]{0,2}){3,}|(\*+[ ]{0,2}){3,})[ ]*$` with
 * the multiline flag. Returns `{ start, end }` of the first matching line.
 */
export function searchHorizontalRule(block) {
  let lineStart = 0;
  while (lineStart <= block.length) {
    let lineEnd = block.indexOf('\n', lineStart);
    if (lineEnd === -1) lineEnd = block.length;
    const line = block.slice(lineStart, lineEnd);
    for (const marker of ['-', '_', '*']) {
      let i = leadingSpaces(line, 0, 3);
      let groups = 0;
      let ok = true;
      while (i < line.length && line[i] === marker) {
        while (line[i] === marker) i += 1;
        i += leadingSpaces(line, i, 2);
        groups += 1;
      }
      if (groups < 3) ok = false;
      if (ok) {
        let j = i;
        while (line[j] === ' ') j += 1;
        if (j === line.length) return { start: lineStart, end: lineEnd };
      }
    }
    if (lineEnd === block.length) break;
    lineStart = lineEnd + 1;
  }
  return null;
}

/** `(^|\n)[ ]{0,3}>[ ]?(.*)` searched from the start of `block`. */
export function searchBlockQuote(block) {
  for (let pos = 0; pos <= block.length; pos += 1) {
    if (pos > 0 && block[pos - 1] !== '\n') continue;
    const indent = leadingSpaces(block, pos, 3);
    let i = pos + indent;
    if (block[i] !== '>') continue;
    i += 1;
    if (block[i] === ' ') i += 1;
    let end = block.indexOf('\n', i);
    if (end === -1) end = block.length;
    return {
      start: pos > 0 ? pos - 1 : 0,
      end,
      content: block.slice(i, end)
    };
  }
  return null;
}

/** `^[ ]{0,3}\d+\.[ ]+(.*)` anchored at the start of `line`. */
export function matchOrderedItem(line) {
  const indent = leadingSpaces(line, 0, TAB_LENGTH - 1);
  let i = indent;
  const digits = i;
  while (isDigit(line[i])) i += 1;
  if (i === digits) return null;
  if (line[i] !== '.') return null;
  i += 1;
  const spaces = i;
  while (line[i] === ' ') i += 1;
  if (i === spaces) return null;
  return { number: line.slice(digits, digits + (i - spaces) * 0 + (spaces - digits - 1)), content: line.slice(i) };
}

/** `^[ ]{0,3}[*+-][ ]+(.*)` anchored at the start of `line`. */
export function matchUnorderedItem(line) {
  const indent = leadingSpaces(line, 0, TAB_LENGTH - 1);
  let i = indent;
  if ('*+-'.indexOf(line[i]) === -1 || line[i] === undefined) return null;
  i += 1;
  const spaces = i;
  while (line[i] === ' ') i += 1;
  if (i === spaces) return null;
  return { content: line.slice(i) };
}

/**
 * `^[ ]{0,3}((\d+\.)|[*+-])[ ]+(.*)` anchored at the start of `line`; matches a
 * list item of either kind. Returns the marker and the item content.
 */
export function matchAnyItem(line) {
  const indent = leadingSpaces(line, 0, TAB_LENGTH - 1);
  let i = indent;
  let marker = '';
  const digitStart = i;
  while (isDigit(line[i])) i += 1;
  if (i > digitStart) {
    if (line[i] !== '.') return null;
    i += 1;
    marker = line.slice(digitStart, i);
  } else {
    if (line[i] === undefined || '*+-'.indexOf(line[i]) === -1) return null;
    marker = line[i];
    i += 1;
  }
  const spaces = i;
  while (line[i] === ' ') i += 1;
  if (i === spaces) return null;
  return { marker, content: line.slice(i) };
}

/** `^[ ]{4,7}((\d+\.)|[*+-])[ ]+.*` anchored at the start of `line`. */
export function isIndentedItem(line) {
  let indent = 0;
  while (line[indent] === ' ') indent += 1;
  if (indent < TAB_LENGTH || indent > TAB_LENGTH * 2 - 1) return false;
  return matchAnyItem(line.slice(indent)) !== null;
}

/** `^(([ ]{4})+)` anchored at the start of `block`. */
export function matchIndentLevel(block) {
  let count = 0;
  while (block.startsWith(' '.repeat(TAB_LENGTH), count * TAB_LENGTH)) count += 1;
  return count;
}

/**
 * `^[ ]{0,3}\[([^\[\]]*)\]:[ ]*\n?[ ]*([^\s]+)[ ]*(?:\n?[ ]*((["'])(.*)\4|\((.*)\))[ ]*)?$`
 * with the multiline flag, searched from the start of `block`.
 */
export function searchReference(block) {
  let lineStart = 0;
  while (lineStart <= block.length) {
    const found = matchReferenceAt(block, lineStart);
    if (found) return found;
    const nl = block.indexOf('\n', lineStart);
    if (nl === -1) break;
    lineStart = nl + 1;
  }
  return null;
}

function skipOptionalNewlineAndSpaces(block, index) {
  let i = index;
  while (block[i] === ' ') i += 1;
  if (block[i] === '\n') {
    i += 1;
    while (block[i] === ' ') i += 1;
  }
  return i;
}

/** True when the pattern's `$` (multiline) can match at `index`. */
function atLineEnd(block, index) {
  return index >= block.length || block[index] === '\n';
}

function matchReferenceAt(block, start) {
  let i = start + leadingSpaces(block, start, 3);
  if (block[i] !== '[') return null;
  i += 1;
  const idStart = i;
  while (i < block.length && block[i] !== '[' && block[i] !== ']') i += 1;
  if (block[i] !== ']') return null;
  const id = block.slice(idStart, i);
  i += 1;
  if (block[i] !== ':') return null;
  i += 1;
  while (block[i] === ' ') i += 1;
  if (block[i] === '\n') {
    i += 1;
    while (block[i] === ' ') i += 1;
  }
  const linkStart = i;
  while (i < block.length && !isSpaceChar(block[i])) i += 1;
  if (i === linkStart) return null;
  const link = block.slice(linkStart, i);
  const afterLink = i;
  while (block[i] === ' ') i += 1;
  const beforeTitle = i;

  // Optional title, on this line or the next.
  const titleStart = skipOptionalNewlineAndSpaces(block, afterLink);
  const quote = block[titleStart];
  if (quote === '"' || quote === "'" || quote === '(') {
    const closer = quote === '(' ? ')' : quote;
    // `(.*)` cannot span lines, so search within the current line only.
    let lineEnd = block.indexOf('\n', titleStart);
    if (lineEnd === -1) lineEnd = block.length;
    const lastCloser = block.lastIndexOf(closer, lineEnd - 1);
    if (lastCloser > titleStart) {
      let after = lastCloser + 1;
      while (block[after] === ' ') after += 1;
      if (atLineEnd(block, after)) {
        return {
          start,
          end: after,
          id,
          link,
          title: block.slice(titleStart + 1, lastCloser)
        };
      }
    }
  }
  if (atLineEnd(block, beforeTitle)) {
    return { start, end: beforeTitle, id, link, title: null };
  }
  return null;
}

