// Common behaviour of the block level processors.

import { TAB_LENGTH } from '../util/constants.mjs';
import { hasContent } from '../util/strings.mjs';

export class BlockProcessor {
  constructor(parser) {
    this.parser = parser;
    this.tabLength = TAB_LENGTH;
  }

  /** Last child of `parent`, or `null`. */
  lastChild(parent) {
    return parent.lastChild;
  }

  /**
   * Remove one level of indentation from the front of each line, stopping at
   * the first line which is not indented. Returns `[detabbed, rest]`.
   */
  detab(text, length) {
    const width = length === undefined ? this.tabLength : length;
    const indent = ' '.repeat(width);
    const lines = String(text).split('\n');
    const kept = [];
    for (const line of lines) {
      if (line.startsWith(indent)) kept.push(line.slice(width));
      else if (!hasContent(line)) kept.push('');
      else break;
    }
    return [kept.join('\n'), lines.slice(kept.length).join('\n')];
  }

  /** Remove indentation from the lines which have it, keeping the others. */
  looseDetab(text, level = 1) {
    const width = this.tabLength * level;
    const indent = ' '.repeat(width);
    return String(text)
      .split('\n')
      .map(line => (line.startsWith(indent) ? line.slice(width) : line))
      .join('\n');
  }

  test() {
    return false;
  }

  run() {}
}

