// Empty blocks, indented code blocks, horizontal rules and paragraphs.

import { BlockProcessor } from './base.mjs';
import { searchHorizontalRule } from './scanners.mjs';
import { subElement, atomic } from '../tree/element.mjs';
import { codeEscape } from '../util/escape.mjs';
import { hasContent, lstrip, rstrip } from '../util/strings.mjs';

export class EmptyBlockProcessor extends BlockProcessor {
  test(parent, block) {
    return !block || block.startsWith('\n');
  }

  run(parent, blocks) {
    const block = blocks.shift();
    let filler = '\n\n';
    if (block) {
      // Starts with an empty line; only that one line is consumed here.
      filler = '\n';
      const theRest = block.slice(1);
      if (theRest) blocks.unshift(theRest);
    }
    const sibling = this.lastChild(parent);
    if (sibling !== null && sibling.tag === 'pre' && sibling.length &&
        sibling.children[0].tag === 'code') {
      // Preserve the whitespace of a preceding code block.
      const code = sibling.children[0];
      code.text = atomic(String(code.text) + filler);
    }
  }
}

export class CodeBlockProcessor extends BlockProcessor {
  test(parent, block) {
    return block.startsWith(' '.repeat(this.tabLength));
  }

  run(parent, blocks) {
    const sibling = this.lastChild(parent);
    const original = blocks.shift();
    let block;
    let theRest;
    if (sibling !== null && sibling.tag === 'pre' && sibling.length &&
        sibling.children[0].tag === 'code') {
      // Blank lines do not start a new code block, so append to the previous.
      const code = sibling.children[0];
      [block, theRest] = this.detab(original);
      code.text = atomic(String(code.text) + '\n' + codeEscape(rstrip(block)) + '\n');
    } else {
      const pre = subElement(parent, 'pre');
      const code = subElement(pre, 'code');
      [block, theRest] = this.detab(original);
      code.text = atomic(codeEscape(rstrip(block)) + '\n');
    }
    if (theRest) blocks.unshift(theRest);
  }
}

export class HRProcessor extends BlockProcessor {
  test(parent, block) {
    const match = searchHorizontalRule(block);
    if (match) {
      this.match = match;
      return true;
    }
    return false;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const match = this.match;
    const prelines = rstrip(block.slice(0, match.start), '\n');
    if (prelines) this.parser.parseBlocks(parent, [prelines]);
    subElement(parent, 'hr');
    const postlines = lstrip(block.slice(match.end), '\n');
    if (postlines) blocks.unshift(postlines);
  }
}

export class ParagraphProcessor extends BlockProcessor {
  test() {
    return true;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    if (!hasContent(block)) return;
    if (this.parser.state.isstate('list')) {
      // The parent is a tight list: attach the text rather than wrapping it.
      const sibling = this.lastChild(parent);
      if (sibling !== null) {
        sibling.tail = sibling.tail ? String(sibling.tail) + '\n' + block : '\n' + block;
      } else if (parent.text) {
        parent.text = String(parent.text) + '\n' + block;
      } else {
        parent.text = lstrip(block);
      }
    } else {
      const p = subElement(parent, 'p');
      p.text = lstrip(block);
    }
  }
}

