// ATX (`# heading`) and Setext (underlined) headers.

import { BlockProcessor } from './base.mjs';
import { searchHashHeader, matchSetextHeader } from './scanners.mjs';
import { subElement } from '../tree/element.mjs';
import { strip } from '../util/strings.mjs';

export class HashHeaderProcessor extends BlockProcessor {
  test(parent, block) {
    return searchHashHeader(block) !== null;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const match = searchHashHeader(block);
    if (!match) return;
    const before = block.slice(0, match.start);
    const after = block.slice(match.end);
    if (before) this.parser.parseBlocks(parent, [before]);
    const header = subElement(parent, 'h' + match.level);
    header.text = strip(match.header);
    if (after) blocks.unshift(after);
  }
}

export class SetextHeaderProcessor extends BlockProcessor {
  test(parent, block) {
    return matchSetextHeader(block) !== null;
  }

  run(parent, blocks) {
    const lines = blocks.shift().split('\n');
    const level = lines[1].startsWith('=') ? 1 : 2;
    const header = subElement(parent, 'h' + level);
    header.text = strip(lines[0]);
    if (lines.length > 2) blocks.unshift(lines.slice(2).join('\n'));
  }
}

